const isAliveNextGeneration = (
  cell: Cell,
  liveIdentities: Set<string>,
): boolean => {
  const liveNeighbors = countLiveNeighbors(cell, liveIdentities);
  return liveIdentities.has(identityOf(cell))
    ? SURVIVAL_NEIGHBOR_COUNTS.includes(liveNeighbors)
    : liveNeighbors === BIRTH_NEIGHBOR_COUNT;
};

export const nextGeneration = (liveCells: Cell[]): Cell[] => {
  const liveIdentities = new Set(liveCells.map(identityOf));
  return candidates(liveCells).filter((cell) =>
    isAliveNextGeneration(cell, liveIdentities),
  );
};
